(function () {
'use strict';
if (window.acfBlocksCouponBound) {
return;
}
window.acfBlocksCouponBound = true;
function markCopied(btn) {
var textSpan = btn.querySelector('.btn-text');
if (!textSpan) {
return;
}
var original = textSpan.textContent;
textSpan.textContent = btn.getAttribute('data-copied-label') || 'Copied!';
window.setTimeout(function () {
textSpan.textContent = original;
}, 2000);
}
function fallbackCopy(code) {
var field = document.createElement('textarea');
field.value = code;
field.setAttribute('readonly', 'readonly');
field.style.position = 'fixed';
field.style.left = '-9999px';
document.body.appendChild(field);
field.select();
var ok = false;
try {
ok = document.execCommand('copy');
} catch (error) {
ok = false;
}
document.body.removeChild(field);
return ok;
}
document.addEventListener('click', function (event) {
var target = event.target;
var btn = target && target.closest ? target.closest('.acf-coupon-copy-btn') : null;
if (!btn) {
return;
}
var code = btn.getAttribute('data-code') || '';
if (!code) {
return;
}
if (navigator.clipboard && navigator.clipboard.writeText) {
navigator.clipboard.writeText(code).then(function () {
markCopied(btn);
}).catch(function () {
if (fallbackCopy(code)) {
markCopied(btn);
}
});
return;
}
if (fallbackCopy(code)) {
markCopied(btn);
}
});
})();
